/**
 * Seed ĐỀ XUẤT — nội dung tiếng Anh (từ vựng, ngữ pháp, luyện tập trắc nghiệm) nhập từ dự án tham khảo
 * `web-study-english` (mảng TypeScript hard-code, không có JSON/markdown gốc) — viết lại/diễn đạt lại
 * cho phù hợp `StudyItemType` hiện có, KHÔNG copy nguyên văn. Dùng lại đúng user hệ thống "Nội dung mẫu"
 * của `lessons.seed.ts` (KHÔNG tạo user mới). Idempotent theo tag `seed:<slug>` — CHỈ TẠO bộ khi tag đó
 * CHƯA có của user này; KHÔNG BAO GIỜ ghi đè/xoá bộ đã tồn tại.
 *
 * Giấy phép: KHÔNG đọc/dùng `drive-topics.json` của dự án tham khảo (nội dung từ khoá học trả phí).
 * CHƯA nhập (không có `StudyItemType` phù hợp — cần tính năng mới):
 *  - `seeds/pronunciation-prompts.ts` (30 câu luyện phát âm A1–B2) — cần chấm phát âm qua audio.
 *  - Câu hỏi dạng `matching`/`ordering` trong `seed-lessons-and-quiz.ts`/`seed-multi-level-lessons.ts`
 *    (ghép cặp / sắp xếp từ) — chưa có loại mục tương ứng.
 */

const CONTENT_OWNER_EMAIL = "content-seed@superapp.local";
const CONTENT_OWNER_NAME = "Nội dung mẫu";

type SeedItem =
  | { type: "FLASHCARD"; prompt: string; answerText: string; tags?: readonly string[] }
  | { type: "MULTIPLE_CHOICE"; prompt: string; options: readonly string[]; correctIndex: number; tags?: readonly string[] }
  | { type: "FILL_BLANK"; prompt: string; acceptedAnswers: readonly string[]; tags?: readonly string[] };

interface SeedSet {
  /** Khoá ổn định để nhận diện bộ đã seed (lưu trong tag `seed:<slug>`) — KHÔNG đổi sau khi đã seed ở môi trường nào. */
  slug: string;
  title: string;
  description: string;
  tags: readonly string[];
  language: string;
  items: readonly SeedItem[];
}

/** Bản sao/mở rộng của `buildItemContent` trong `lessons.seed.ts` — thêm nhánh FILL_BLANK cho bài tập ngữ pháp/quiz. */
function buildItemContent(item: SeedItem): StudyItemContent {
  const tags = normalizeTags(item.tags ?? []);
  const base = { explanation: null, frontMediaAssetId: null, backMediaAssetId: null, audioAssetId: null, tags };
  switch (item.type) {
    case "FLASHCARD":
      return { ...base, type: "FLASHCARD", prompt: item.prompt, answerText: item.answerText, options: [], correctOptionIds: [], acceptedAnswers: [], matchMode: "IGNORE_CASE" };
    case "MULTIPLE_CHOICE": {
      const options = item.options.map((text) => ({ id: newOptionId(), text, mediaAssetId: null }));
      return { ...base, type: "MULTIPLE_CHOICE", prompt: item.prompt, answerText: null, options, correctOptionIds: [options[item.correctIndex].id], acceptedAnswers: [], matchMode: "IGNORE_CASE" };
    }
    case "FILL_BLANK":
      return { ...base, type: "FILL_BLANK", prompt: item.prompt, answerText: null, options: [], correctOptionIds: [], acceptedAnswers: [...item.acceptedAnswers], matchMode: "IGNORE_CASE" };
  }
}

